-- 2) Verify
SELECT COUNT(*) FILTER (WHERE brand IS NOT NULL) AS with_brand,   -- expect 31,871
       COUNT(*) FILTER (WHERE brand IS NULL)     AS without_brand
FROM public.products;

-- 3) Top brands (spot check)
SELECT brand, COUNT(*) AS products
FROM public.products
WHERE brand IS NOT NULL
GROUP BY brand
ORDER BY products DESC
LIMIT 100;

